"""Generate an A2A ``AgentCard`` from a loaded Rasa ``FlowsList``."""

from __future__ import annotations

from typing import TYPE_CHECKING, Optional

from a2a.types import AgentCapabilities, AgentCard, AgentInterface, AgentSkill
from a2a.utils.constants import (
    PROTOCOL_VERSION_0_3,
    PROTOCOL_VERSION_1_0,
    TransportProtocol,
)

from rasa.core.a2a_server.config import A2AServerSettings

if TYPE_CHECKING:
    from rasa.shared.core.flows import Flow, FlowsList


def jsonrpc_supported_interfaces(url: str) -> list[AgentInterface]:
    """JSON-RPC bindings for native 1.0 and v0.3 clients on the same URL."""
    return [
        AgentInterface(
            protocol_binding=TransportProtocol.JSONRPC,
            protocol_version=PROTOCOL_VERSION_1_0,
            url=url,
        ),
        AgentInterface(
            protocol_binding=TransportProtocol.JSONRPC,
            protocol_version=PROTOCOL_VERSION_0_3,
            url=url,
        ),
    ]


class AgentCardGenerator:
    """Build an ``AgentCard`` that advertises flow jurisdiction."""

    @classmethod
    def generate(
        cls,
        config: A2AServerSettings,
        flows: "FlowsList",
        *,
        include_conversation_repair: bool = True,
        port: Optional[int] = None,
        interface: Optional[str] = None,
        scheme: Optional[str] = None,
        assistant_name: Optional[str] = None,
        version: str = "1.0.0",
    ) -> AgentCard:
        """Generate a card from flows advertised as skills.

        User flows that orchestrators can start directly are included; flows
        guarded with ``if: false`` (link-only / ``call: flow`` sub-flows) are
        excluded via ``exclude_link_only_flows()``. Pattern/system flows
        (``pattern_*``) are included only when ``include_conversation_repair``
        is ``True`` (the default), so orchestrators know Rasa handles
        conversation repair.
        """
        return cls.card_from_skills(
            config,
            cls.skills_from_flows(
                flows, include_conversation_repair=include_conversation_repair
            ),
            port=port,
            interface=interface,
            scheme=scheme,
            assistant_name=assistant_name,
            version=version,
        )

    @classmethod
    def skills_from_flows(
        cls,
        flows: "FlowsList",
        *,
        include_conversation_repair: bool = True,
    ) -> list[AgentSkill]:
        """Return the AgentCard skills for *flows*.

        The CALM adapter calls this. URL and assistant name stay with the
        shared card builder.
        """
        advertised_flows = cls._flows_for_skills(
            flows, include_conversation_repair=include_conversation_repair
        )
        return [
            cls._skill_from_flow(flow)
            for flow in sorted(advertised_flows, key=lambda flow: flow.id)
        ]

    @classmethod
    def card_from_skills(
        cls,
        config: A2AServerSettings,
        skills: list[AgentSkill],
        *,
        port: Optional[int] = None,
        interface: Optional[str] = None,
        scheme: Optional[str] = None,
        assistant_name: Optional[str] = None,
        version: str = "1.0.0",
    ) -> AgentCard:
        """Build the card shell around skills an engine adapter already chose."""
        return AgentCard(
            name=assistant_name or "Rasa Agent",
            description=config.description,
            supported_interfaces=jsonrpc_supported_interfaces(
                config.effective_url(port=port, interface=interface, scheme=scheme)
            ),
            version=version,
            default_input_modes=["text", "text/plain"],
            default_output_modes=["text", "text/plain"],
            capabilities=AgentCapabilities(
                streaming=True,
                push_notifications=config.push_notifications_enabled,
            ),
            skills=skills,
        )

    @staticmethod
    def _flows_for_skills(
        flows: "FlowsList", *, include_conversation_repair: bool
    ) -> list["Flow"]:
        advertised = list(flows.user_flows.exclude_link_only_flows().underlying_flows)
        if include_conversation_repair:
            advertised.extend(
                flow for flow in flows.underlying_flows if flow.is_rasa_default_flow
            )
        return advertised

    @staticmethod
    def _skill_from_flow(flow: "Flow") -> AgentSkill:
        description = flow.description or flow.readable_name()
        return AgentSkill(
            id=flow.id,
            name=flow.readable_name(),
            description=description,
            tags=[flow.id],
        )
